    <script>
        (()=>{const rows=[...document.querySelectorAll('[data-row-select]')],alls=[...document.querySelectorAll('[data-select-all]')],buttons=[...document.querySelectorAll('[data-bulk-action]')],action=document.getElementById('posts-bulk-action'),form=document.getElementById('posts-bulk-form');function refresh(){const count=rows.filter(row=>row.checked).length;buttons.forEach(button=>button.disabled=count===0);alls.forEach(all=>{all.checked=count>0&&count===rows.length;all.indeterminate=count>0&&count<rows.length;});}rows.forEach(row=>row.addEventListener('change',refresh));alls.forEach(all=>all.addEventListener('change',()=>{rows.forEach(row=>row.checked=all.checked);refresh();}));buttons.forEach(button=>button.addEventListener('click',()=>{action.value=button.dataset.bulkAction;form.requestSubmit();}));if(location.hash){const post=document.querySelector(location.hash);if(post?.tagName==='DETAILS')post.open=true;}refresh();})();
    </script>
